#!/bin/bash
#---------------------------------------------------------------------------
# run_sim.sh : the BIOS on mmRISC-3 in simulation (step 2.6, docs/BRINGUP.md 28):
#              litex_sim's SoC (the same cpu/mmrisc3, LiteDRAM with its SDRAM
#              model, the UART), generated by LiteX, run by sim_main.cpp
#
#   ./LitexSystem/sim/run_sim.sh [max_cycles [command]]
#
# One clock: the CPU on sys (no crossing; the board's crossings are mmRISC-2's,
# steps 2.2 to 2.5). Out in /tmp/... (OUT=<dir>); PASS when the BIOS gives
# its prompt (and, with a command, the prompt after it).
#---------------------------------------------------------------------------
set -e
HERE=$(cd "$(dirname "$0")" && pwd)
LITEX_SYSTEM=$(dirname "$HERE")
REPO=$(dirname "$LITEX_SYSTEM")
LITEX_HOME=${LITEX_HOME:-$(cd "$REPO/../mmRISC-2/LitexRocket" && pwd)}
OUT=${OUT:-$(mktemp -d)}
mkdir -p "$OUT"
source "$LITEX_HOME/.venv/bin/activate"
export PATH=/opt/riscv/bin:$PATH
cd "$LITEX_SYSTEM/cpu"
python3 -m litex.tools.litex_sim --cpu-type mmrisc3 --with-sdram --sdram-module MT41K128M16 \
    --sdram-data-width 16 --non-interactive --l2-size 0 --no-compile-gateware --output-dir "$OUT" > "$OUT/gen.log" 2>&1 \
    || { echo "run_sim: LiteX failed (see $OUT/gen.log)"; exit 1; }
SRC=$(sed -n 's/.*CC_SRCS="\(.*\)" OPT_LEVEL.*/\1/p' "$OUT/gateware/build_sim.sh" | sed 's/--cc //g')
cd "$OUT/gateware"
verilator --cc --exe --build -j 8 -O2 -Wno-fatal -Wno-WIDTH -Wno-UNOPTFLAT -Wno-lint -Wno-style \
    --top-module sim --Mdir obj $SRC "$HERE/sim_main.cpp" -CFLAGS -O2 > "$OUT/build.log" 2>&1 \
    || { echo "run_sim: Verilator failed (see $OUT/build.log)"; exit 1; }
echo "run_sim: in $OUT/gateware"
./obj/Vsim "$@"
